/// <reference types="node" />

import type { OutputFormat, Output, AnyInput, ChunkedInput } from './types'

export interface CompressOptions<F extends OutputFormat = 'uint8'> {
  format?: F
}

export function gzip<F extends OutputFormat = 'uint8'>(
  data: AnyInput,
  options?: CompressOptions<F>
): Promise<Output<F>>

export function gunzip<F extends OutputFormat = 'uint8'>(
  data: ChunkedInput,
  options?: CompressOptions<F>
): Promise<Output<F>>

export function deflate<F extends OutputFormat = 'uint8'>(
  data: AnyInput,
  options?: CompressOptions<F>
): Promise<Output<F>>

export function inflate<F extends OutputFormat = 'uint8'>(
  data: ChunkedInput,
  options?: CompressOptions<F>
): Promise<Output<F>>

export function deflateRaw<F extends OutputFormat = 'uint8'>(
  data: AnyInput,
  options?: CompressOptions<F>
): Promise<Output<F>>

export function inflateRaw<F extends OutputFormat = 'uint8'>(
  data: ChunkedInput,
  options?: CompressOptions<F>
): Promise<Output<F>>
